import os
from azure.ai.contentsafety import ContentSafetyClient
from azure.core.credentials import AzureKeyCredential


def get_azure_content_safety_client(config=None):
    config = config or {}
    endpoint = config.get('AZURE_CONTENT_SAFETY_ENDPOINT', os.environ.get('AZURE_CONTENT_SAFETY_ENDPOINT'))
    api_key = config.get('AZURE_CONTENT_SAFETY_KEY', os.environ.get('AZURE_CONTENT_SAFETY_KEY'))

    if not endpoint or not api_key:
        raise ValueError("Azure Content Safety endpoint and API key must be provided.")

    return ContentSafetyClient(endpoint, AzureKeyCredential(api_key))

from typing import List
from azure.ai.contentsafety.models import AnalyzeTextOptions, TextCategory
from safety_client import get_azure_content_safety_client
from safety_models import BatchModerationRequest, BatchModerationResponse, MessageDecision


def moderate_batch(payload: BatchModerationRequest, config=None) -> BatchModerationResponse:
    client = get_azure_content_safety_client(config)
    decisions: List[MessageDecision] = []

    for text_to_moderate in payload.texts:
        response = client.analyze_text(AnalyzeTextOptions(text=text_to_moderate, output_type='EightSeverityLevels'))

        is_flagged = False
        reasons = []
        for category_analysis in response.categories_analysis:
            if category_analysis.severity > 0:
                is_flagged = True
                reasons.append(f"{TextCategory(category_analysis.category).name} (severity: {category_analysis.severity})")

        decision = "allow"
        if is_flagged:
            decision = "flag"

        decisions.append(MessageDecision(text=text_to_moderate, decision=decision, reasons=reasons))

    return BatchModerationResponse(decisions=decisions)

from azure.ai.contentsafety.models import AnalyzeTextOptions, TextCategory
from safety_client import get_azure_content_safety_client
from safety_models import RedactRequest, RedactResponse


def redact_unsafe(payload: RedactRequest, config=None) -> RedactResponse:
    client = get_azure_content_safety_client(config)
    response = client.analyze_text(AnalyzeTextOptions(text=payload.text, output_type='EightSeverityLevels', blocklist_names=[]))

    redacted_text = payload.text
    is_unsafe = False

    if response.harm_sentence_analysis is not None:
        for sentence in response.harm_sentence_analysis:
            if sentence.blocklists_match is not None:
                for block_match in sentence.blocklists_match:
                    for match_text in block_match.matching_text:
                        redacted_text = redacted_text.replace(match_text, "[REDACTED]")
                        is_unsafe = True

    for category_analysis in response.categories_analysis:
        if category_analysis.severity > 0:
            is_unsafe = True
            break

    return RedactResponse(redacted_text=redacted_text, is_unsafe=is_unsafe)

from safety_models import SafetyThresholdRequest, MessageDecision
from typing import List


def safety_threshold(payload: SafetyThresholdRequest) -> MessageDecision:
    moderation_result = payload.moderation_result
    threshold_configs = payload.threshold_configs

    decision = "allow"
    reasons: List[str] = []

    for category_analysis in moderation_result.categories:
        for threshold_config in threshold_configs:
            if category_analysis.category == threshold_config.category and category_analysis.severity >= threshold_config.threshold:
                decision = threshold_config.action
                reasons.append(f"{category_analysis.category} exceeded threshold (severity: {category_analysis.severity}, threshold: {threshold_config.threshold})")
                if decision == "block":
                    break
        if decision == "block":
            break

    return MessageDecision(text=moderation_result.text, decision=decision, reasons=reasons)

import os
import google.generativeai as genai
from safety_models import ModerationSummaryRequest, ModerationSummaryResponse


def moderation_summary(payload: ModerationSummaryRequest, config=None) -> ModerationSummaryResponse:
    config = config or {}
    genai.configure(api_key=config.get('GOOGLE_API_KEY', os.environ.get('GOOGLE_API_KEY')))
    model = genai.GenerativeModel('gemini-pro')

    decision_strings = []
    for decision in payload.decisions:
        decision_strings.append(f"Text: {decision.text}, Decision: {decision.decision}, Reasons: {', '.join(decision.reasons)}")

    prompt = f"Summarize the following moderation decisions:\n" + "\n".join(decision_strings)

    response = model.generate_content(prompt)
    return ModerationSummaryResponse(summary=response.text)

import os
from google.cloud import translate_v2 as translate
from safety_models import AppealTranslateRequest, AppealTranslateResponse


def appeal_translate(payload: AppealTranslateRequest, config=None) -> AppealTranslateResponse:
    config = config or {}
    # Google Cloud Translation client automatically uses GOOGLE_APPLICATION_CREDENTIALS or default credentials
    client = translate.Client()

    result = client.translate(payload.appeal_text, target_language=payload.target_language)
    translated_text = result['translatedText']

    return AppealTranslateResponse(translated_text=translated_text)
